'use strict';

/**
 * Sliding-window rate limiting middleware for Express.
 *
 * This is a TRUE sliding window: every request timestamp is stored per client,
 * and on each request all timestamps older than `windowMs` are evicted before
 * counting. There is no fixed interval that resets the counter, so a client
 * cannot burst 2x maxRequests across a window boundary.
 *
 * NOTE ON `req.ip` AND PROXIES:
 *   By default Express sets `req.ip` from the socket's remote address. If your
 *   app runs behind a reverse proxy / load balancer (nginx, ELB, Cloudflare,
 *   Heroku, Render, ...), every request will appear to come from the proxy's IP
 *   and all clients will share a single bucket. Enable trust proxy so Express
 *   derives `req.ip` from the `X-Forwarded-For` header:
 *
 *       app.set('trust proxy', 1);          // trust the first hop (typical)
 *       app.set('trust proxy', 'loopback'); // or a subnet / list of proxies
 *
 *   Only trust proxies you actually control — `X-Forwarded-For` is
 *   client-spoofable, and a too-permissive setting lets an attacker forge a
 *   fresh IP per request and bypass the limiter entirely. Avoid
 *   `app.set('trust proxy', true)` on a publicly reachable app unless every hop
 *   in front of it is trusted.
 */

const DEFAULT_WINDOW_MS = 60 * 1000;
const DEFAULT_MAX_REQUESTS = 100;
const CLEANUP_INTERVAL_MS = 60 * 1000;

/**
 * @param {object} [options]
 * @param {number} [options.windowMs=60000]          Window size in milliseconds.
 * @param {number} [options.maxRequests=100]         Max requests allowed per window.
 * @param {number} [options.cleanupIntervalMs=60000] How often to sweep idle clients.
 * @param {(req) => string} [options.keyGenerator]   Bucket key. Defaults to `req.ip`.
 * @returns {Function & { close(): void, reset(): void, size(): number }}
 */
function createRateLimiter(options = {}) {
  const {
    windowMs = DEFAULT_WINDOW_MS,
    maxRequests = DEFAULT_MAX_REQUESTS,
    cleanupIntervalMs = CLEANUP_INTERVAL_MS,
    keyGenerator = (req) => req.ip,
  } = options;

  if (!Number.isFinite(windowMs) || windowMs <= 0) {
    throw new TypeError('windowMs must be a positive finite number');
  }
  if (!Number.isInteger(maxRequests) || maxRequests < 0) {
    throw new TypeError('maxRequests must be a non-negative integer');
  }

  /**
   * key -> array of request timestamps (ms epoch), kept in ascending order
   * because we only ever push "now".
   * @type {Map<string, number[]>}
   */
  const hits = new Map();

  /**
   * Drop every timestamp older than the window, in place. Timestamps are sorted
   * ascending, so the expired ones form a prefix — find the first survivor and
   * splice the prefix off.
   */
  function evictExpired(timestamps, cutoff) {
    let firstValid = 0;
    while (firstValid < timestamps.length && timestamps[firstValid] <= cutoff) {
      firstValid += 1;
    }
    if (firstValid > 0) timestamps.splice(0, firstValid);
    return timestamps;
  }

  function middleware(req, res, next) {
    const key = keyGenerator(req);

    // If we can't identify the client, fail open rather than lumping every
    // unidentifiable request into one shared bucket.
    if (key === undefined || key === null || key === '') {
      return next();
    }

    const now = Date.now();
    const cutoff = now - windowMs; // older than the window => expired

    let timestamps = hits.get(key);
    if (timestamps === undefined) {
      timestamps = [];
      hits.set(key, timestamps);
    }
    evictExpired(timestamps, cutoff);

    if (timestamps.length >= maxRequests) {
      // Over the limit. The oldest surviving timestamp must age out before a
      // slot frees up.
      const oldest = timestamps[0];
      const msUntilFree = oldest + windowMs - now;
      const retryAfter = Math.max(1, Math.ceil(msUntilFree / 1000));
      const resetEpochSeconds = Math.ceil((now + msUntilFree) / 1000);

      res.setHeader('X-RateLimit-Limit', String(maxRequests));
      res.setHeader('X-RateLimit-Remaining', '0');
      res.setHeader('X-RateLimit-Reset', String(resetEpochSeconds));
      res.setHeader('Retry-After', String(retryAfter));

      res.status(429).json({ error: 'Rate limit exceeded', retryAfter });
      return undefined; // deliberately does NOT call next()
    }

    // Under the limit: record this request and let it through.
    timestamps.push(now);

    const remaining = Math.max(0, maxRequests - timestamps.length);
    // The window "resets" (a slot frees) when the oldest hit ages out.
    const resetEpochSeconds = Math.ceil((timestamps[0] + windowMs) / 1000);

    res.setHeader('X-RateLimit-Limit', String(maxRequests));
    res.setHeader('X-RateLimit-Remaining', String(remaining));
    res.setHeader('X-RateLimit-Reset', String(resetEpochSeconds));

    return next();
  }

  // ---- Memory management -------------------------------------------------
  // Without this sweep, `hits` grows without bound: one entry per IP ever seen.
  const cleanupTimer = setInterval(() => {
    const cutoff = Date.now() - windowMs;
    for (const [key, timestamps] of hits) {
      evictExpired(timestamps, cutoff);
      if (timestamps.length === 0) hits.delete(key);
    }
  }, cleanupIntervalMs);

  // Don't hold the event loop open just for the sweep (Node-only API).
  if (typeof cleanupTimer.unref === 'function') cleanupTimer.unref();

  /** Stop the cleanup timer and release all state. Call on shutdown / in tests. */
  middleware.close = function close() {
    clearInterval(cleanupTimer);
    hits.clear();
  };

  /** Clear all tracked clients without stopping the timer. */
  middleware.reset = function reset() {
    hits.clear();
  };

  /** Number of clients currently tracked — useful for tests / metrics. */
  middleware.size = function size() {
    return hits.size;
  };

  return middleware;
}

module.exports = createRateLimiter;
module.exports.createRateLimiter = createRateLimiter;
```

## Usage

```js
'use strict';

const express = require('express');
const { createRateLimiter } = require('./rateLimiter');

const app = express();

// Behind a reverse proxy? Tell Express how many hops to trust so `req.ip`
// reflects the real client rather than the proxy. Omit if directly exposed.
app.set('trust proxy', 1);

// Global limiter: 100 requests per minute per IP.
const limiter = createRateLimiter({ windowMs: 60_000, maxRequests: 100 });
app.use(limiter);

// A tighter limiter for a sensitive route: 5 requests per 15 minutes.
const loginLimiter = createRateLimiter({ windowMs: 15 * 60_000, maxRequests: 5 });

app.get('/', (req, res) => res.json({ ok: true }));
app.post('/login', loginLimiter, (req, res) => res.json({ ok: true }));

const server = app.listen(3000, () => console.log('listening on :3000'));

// Clear the cleanup timers on shutdown so the process can exit.
process.on('SIGTERM', () => {
  server.close();
  limiter.close();
  loginLimiter.close();
});
```

## Design notes

- **Why it's genuinely sliding:** the decision is made purely from `now - windowMs`, recomputed per request. A client that sends 100 requests at `t=0` gets nothing back at `t=59s`, and regains exactly one slot per second starting at `t=60s` — no cliff where the whole budget refills at once.
- **Eviction cost:** timestamps are appended in ascending order, so expired entries are always a prefix; one `splice` per request, amortized O(1) per stored hit.
- **`X-RateLimit-Reset`** is the epoch second at which the *oldest* tracked request ages out — i.e. when the next slot frees, which is the meaningful value for a sliding window (there is no single moment when the whole window resets).
- **`Retry-After`** is floored at 1 second so a client never sees `Retry-After: 0` and hot-loops.
- **Two safety valves beyond the required cleanup:** `unref()` on the timer means it won't keep the process alive even if a caller forgets `close()`, and an unidentifiable key fails open rather than merging all such requests into one shared bucket.
- **Scope:** state is per-process and in-memory. Across multiple instances each replica enforces its own limit, so N replicas allow up to N×`maxRequests`; for a shared limit, back the same algorithm with Redis (a sorted set per key, `ZREMRANGEBYSCORE` + `ZCARD` + `ZADD` in a MULTI or Lua script maps onto this logic one-to-one).

