/**
 * sliding-window-rate-limiter.js
 *
 * A TRUE sliding-window rate limiting middleware for Express.js.
 *
 * Unlike a fixed-window limiter (which resets a counter every N ms and lets
 * bursts straddle the boundary — e.g. 100 requests at 0:59 + 100 more at
 * 1:01 = 200 requests in 2 seconds), this implementation keeps the actual
 * timestamp of every request per client and, on each new request, discards
 * timestamps older than `windowMs` before counting. The window "slides"
 * continuously with the clock instead of snapping back to zero at fixed
 * intervals.
 *
 * NOTE on req.ip / proxies:
 *   Express derives `req.ip` from the socket address unless you set
 *   `app.set('trust proxy', ...)`. If your app sits behind a reverse proxy,
 *   load balancer, or CDN (nginx, ALB, Heroku, Cloudflare, etc.), you MUST
 *   configure `trust proxy` (e.g. `app.set('trust proxy', 1)` for a single
 *   hop, or a specific IP/CIDR list) — otherwise every request will appear
 *   to come from the proxy's IP and all clients will share one bucket, or
 *   conversely a spoofed `X-Forwarded-For` header could let clients evade
 *   the limiter entirely if trust proxy is misconfigured. Validate/sanitize
 *   `req.ip` (or whatever key you derive) accordingly for your deployment.
 */

'use strict';

function createRateLimiter(options = {}) {
  const windowMs = options.windowMs || 60000; // 1 minute default
  const maxRequests = options.maxRequests || 100;

  // Optional: allow callers to override how the client is identified
  // (e.g. API key instead of IP). Defaults to req.ip.
  const keyGenerator =
    typeof options.keyGenerator === 'function'
      ? options.keyGenerator
      : (req) => req.ip;

  // Map<clientKey, number[]> — sorted ascending array of request timestamps (ms)
  const store = new Map();

  function middleware(req, res, next) {
    const key = keyGenerator(req);
    const now = Date.now();
    const windowStart = now - windowMs;

    let timestamps = store.get(key);

    if (!timestamps) {
      timestamps = [];
      store.set(key, timestamps);
    }

    // Remove all timestamps older than the sliding window. Timestamps are
    // appended in increasing order, so we can binary-search / scan from the
    // front instead of filtering the whole array every time.
    let start = 0;
    while (start < timestamps.length && timestamps[start] <= windowStart) {
      start++;
    }
    if (start > 0) {
      timestamps.splice(0, start);
    }

    const currentCount = timestamps.length;

    if (currentCount >= maxRequests) {
      // Oldest timestamp still in the window determines when a slot frees up.
      const oldest = timestamps[0];
      const retryAfterMs = oldest + windowMs - now;
      const retryAfterSec = Math.max(1, Math.ceil(retryAfterMs / 1000));

      res.set('Retry-After', String(retryAfterSec));
      res.set('X-RateLimit-Limit', String(maxRequests));
      res.set('X-RateLimit-Remaining', '0');
      res.set('X-RateLimit-Reset', String(Math.ceil((oldest + windowMs) / 1000)));

      return res.status(429).json({
        error: 'Rate limit exceeded',
        retryAfter: retryAfterSec,
      });
    }

    // Allowed: record this request's timestamp.
    timestamps.push(now);

    const remaining = maxRequests - timestamps.length;
    // Reset time = when the current oldest timestamp will fall out of the
    // window (i.e. when a new slot becomes available if you're at the cap;
    // if not at the cap, it's still a meaningful "window fully clears by").
    const resetAt = timestamps[0] + windowMs;

    res.set('X-RateLimit-Limit', String(maxRequests));
    res.set('X-RateLimit-Remaining', String(Math.max(0, remaining)));
    res.set('X-RateLimit-Reset', String(Math.ceil(resetAt / 1000)));

    next();
  }

  // Periodic cleanup: drop entries for clients with no requests in the
  // last windowMs, so the Map doesn't grow unbounded with stale IPs.
  const cleanupIntervalMs = options.cleanupIntervalMs || 60000;
  const cleanupTimer = setInterval(() => {
    const now = Date.now();
    const windowStart = now - windowMs;

    for (const [key, timestamps] of store.entries()) {
      // Trim stale timestamps first.
      let start = 0;
      while (start < timestamps.length && timestamps[start] <= windowStart) {
        start++;
      }
      if (start > 0) {
        timestamps.splice(0, start);
      }
      if (timestamps.length === 0) {
        store.delete(key);
      }
    }
  }, cleanupIntervalMs);

  // Don't let the cleanup timer keep the Node process alive on its own
  // (e.g. during tests or graceful shutdown), if unref is available.
  if (typeof cleanupTimer.unref === 'function') {
    cleanupTimer.unref();
  }

  middleware.close = function close() {
    clearInterval(cleanupTimer);
    store.clear();
  };

  // Expose the store for testing/inspection if needed.
  middleware.store = store;

  return middleware;
}

module.exports = { createRateLimiter };
